    return await request();
  } catch (error) {
    if (attempts <= 1) throw error;
    const delay = baseDelay * 2 ** (3 - attempts);
    await new Promise(resolve => setTimeout(resolve, delay));
    return retry(request, attempts - 1, baseDelay);
